#define N 1024
int matrix[N][N];

// Cache-Friendly: Row-Major Traversal (Spatial Locality)
for (int i=0; i<N; ++i)
  for (int j=0; j<N; ++j)
    matrix[i][j] += 1;

// Cache-Unfriendly: Column-Major (High Stride/Low Locality)
for (int j=0; j<N; ++j)
  for (int i=0; i<N; ++i)
    matrix[i][j] += 1;

