// Cache Blocking (Temporal Locality optimization, e.g., Matrix Mul)
#define BLOCK_SIZE 32 // Must fit within cache (L1/L2)
void blocked_mult(int N) {
    for (int bk = 0; bk < N; bk += BLOCK_SIZE)
        for (int bj = 0; bj < N; bj += BLOCK_SIZE)
            for (int i = 0; i < N; ++i)
                for (int j = bj; j < bj + BLOCK_SIZE; ++j)
                    for (int k = bk; k < bk + BLOCK_SIZE; ++k)
                        C[i][j] += A[i][k] * B[k][j];
} // Maximize reuse of A and B blocks while resident in cache
